'use strict';

function parseAmountToCents(raw) {
  if (typeof raw === 'number') {
    if (!Number.isFinite(raw)) throw new TypeError(`importe no valido: ${raw}`);
    return Math.round(raw * 100);
  }
  const text = String(raw).trim().replace(',', '.');
  if (!/^-?\d+(\.\d+)?$/.test(text)) throw new TypeError(`importe no valido: ${raw}`);
  const value = Number.parseFloat(text);
  return Math.round(value * 100);
}

function formatCents(cents) {
  if (!Number.isInteger(cents)) throw new TypeError(`centavos no enteros: ${cents}`);
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  const units = Math.trunc(abs / 100);
  const rest = abs - units * 100;
  return `${sign}${units}.${String(rest).padStart(2, '0')}`;
}

module.exports = { parseAmountToCents, formatCents };

'use strict';

const { cost } = require('boundary-cost-tools');
const { parseAmountToCents } = require('./parse');

function computeTotals(order) {
  if (!order || !Array.isArray(order.lines) || order.lines.length === 0) {
    throw new TypeError('pedido sin lineas');
  }
  let subtotal = 0;
  let units = 0;
  for (const line of order.lines) {
    if (!Number.isInteger(line.quantity) || line.quantity <= 0) {
      throw new TypeError(`cantidad no valida: ${line.quantity}`);
    }
    subtotal += parseAmountToCents(line.amount) * line.quantity;
    units += line.quantity;
  }
  const discountPercent = order.discountPercent === undefined ? 0 : order.discountPercent;
  if (discountPercent < 0 || discountPercent > 100) {
    throw new RangeError(`descuento fuera de rango: ${discountPercent}`);
  }
  const discount = Math.round((subtotal * discountPercent) / 100);
  const handling = cost(units);
  return { subtotal, discount, handling, total: subtotal - discount + handling };
}

module.exports = { computeTotals };

'use strict';

const { formatCents } = require('./parse');
const { computeTotals } = require('./total');

function renderReport(orders) {
  if (!Array.isArray(orders)) throw new TypeError('se esperaba una lista de pedidos');
  const byCurrency = new Map();
  for (const order of orders) {
    const currency = String(order.currency === undefined ? '' : order.currency).toUpperCase();
    if (currency.length !== 3) throw new TypeError(`moneda no valida: ${order.currency}`);
    const totals = computeTotals(order);
    const acc = byCurrency.get(currency) || { subtotal: 0, discount: 0, handling: 0, total: 0 };
    acc.subtotal += totals.subtotal;
    acc.discount += totals.discount;
    acc.handling += totals.handling;
    acc.total += totals.total;
    byCurrency.set(currency, acc);
  }
  const rows = [];
  for (const [currency, acc] of [...byCurrency.entries()].sort(([a], [b]) => a.localeCompare(b))) {
    rows.push(
      `${currency}: subtotal ${formatCents(acc.subtotal)} | descuento ${formatCents(acc.discount)} | gestion ${formatCents(acc.handling)} | total ${formatCents(acc.total)}`,
    );
  }
  return rows;
}

module.exports = { renderReport };

